func skuTokenTraces(tok, allowedText string, candidateNames []string) bool {
	if strings.Contains(allowedText, tok) { return true }
	for _, n := range candidateNames {
		if strings.Contains(n, tok) || strings.Contains(tok, n) { return true }
	}
	segs := strings.Split(tok, "-")
	for i := len(segs) - 1; i >= 1; i-- {
		head := strings.Join(segs[:i], "-")
		if !strings.Contains(allowedText, head) && !nameOverlaps(head, candidateNames) { continue }
		if allQualifierSegments(segs[i:]) { return true }
	}
	return false
}

func qualifierSegment(s string) bool {
	if len(s) < 2 { return false }
	for _, r := range s {
		if r < 'a' || r > 'z' { return false }
	}
	return true
}

